        /** The table of a language tag („de“, „de-AT“, „en-GB“); an unknown language gets German. */
        fun forLanguage(tag: String): SbMessages = when (tag.lowercase(Locale.ROOT).substringBefore('-')) {
            "en" -> En
            else -> De
        }
    }
