// the date formats of the two built-in tables (D99 (8)): German „28.09.“, „Mittwoch, 21.10.“; English „28 Sep“,
// „Wednesday, 21 Oct“
/**
 * A date with its year and without a weekday, with plain spaces, for text an app stores or searches (a document's
 * default title, a file name; CHECKS.md §80, provisional, agent): „24.10.2026“, „24 Oct 2026“. German for German, English
 * for every other language, as sebaro's two message tables, with no region, so en-GB's „Sept“ stays sebaro's „Sep“ and
 * French gets „24 Oct 2026“. An app with a third language formats its own date. Works outside Compose.
 */
fun sbPlainDate(date: LocalDate, locale: Locale): String =
    date.format(if (locale.language == Locale.GERMAN.language) SB_PLAIN_DATE_DE else SB_PLAIN_DATE_EN)

private val SB_PLAIN_DATE_DE = DateTimeFormatter.ofPattern("dd.MM.yyyy", Locale.GERMAN)
private val SB_PLAIN_DATE_EN = DateTimeFormatter.ofPattern("d MMM yyyy", Locale.ENGLISH)
private val SB_DATE_DE = DateTimeFormatter.ofPattern("dd.MM.", Locale.GERMAN)
private val SB_DAY_DE = DateTimeFormatter.ofPattern("EEEE, dd.MM.", Locale.GERMAN)
private val SB_DATE_EN = DateTimeFormatter.ofPattern("d\u00A0MMM", Locale.ENGLISH)
private val SB_DAY_EN = DateTimeFormatter.ofPattern("EEEE, d\u00A0MMM", Locale.ENGLISH)
// a day of another year spelled out (§14.2): „Samstag, 10. Oktober 2025“, „Saturday, 10 October 2025“; a time of day
// in 24 hours in both tables, „19:00“ (provisional, agent)
private val SB_DAY_YEAR_DE = DateTimeFormatter.ofPattern("EEEE, d. MMMM yyyy", Locale.GERMAN)
private val SB_DAY_YEAR_EN = DateTimeFormatter.ofPattern("EEEE, d\u00A0MMMM yyyy", Locale.ENGLISH)
private val SB_TIME = DateTimeFormatter.ofPattern("HH:mm", Locale.ROOT)

/** Resolve the app locale with the product fallback, never an unconditional German fallback (D126). */
fun sbMessagesFor(locale: Locale, fallback: SbMessages = SbMessages.De): SbMessages = when (locale.language) {
    "de" -> SbMessages.De
    "en" -> SbMessages.En
    else -> fallback
}

/** Resolved product locale (D126); null outside a theme preserves configuration-based legacy consumers. */
val LocalSbAppLocale = staticCompositionLocalOf<Locale?> { null }


/** CHECKS §71: the app's resources in the resolved app locale (D126); null outside a theme with `appLocales`. A local of its
 * own, because Compose's `LocalResources` exists only from Compose UI 1.8 and sebaro builds on BOM 2024.12 too. */
val LocalSbAppResources = androidx.compose.runtime.staticCompositionLocalOf<android.content.res.Resources?> { null }

/** stringResource in the app locale (CHECKS §71): plural rules and %d digits follow the app, not the phone. */
// the LocalContext fallback serves BOM 2024.12, which has no LocalResources (Compose UI < 1.8)
@android.annotation.SuppressLint("LocalContextResourcesRead")
@Composable
fun sbStringResource(id: Int, vararg args: Any): String {
    val res = LocalSbAppResources.current ?: LocalContext.current.resources
    return if (args.isEmpty()) res.getString(id) else res.getString(id, *args)
}

/** pluralStringResource in the app locale (CHECKS §71). */
// the LocalContext fallback serves BOM 2024.12, which has no LocalResources (Compose UI < 1.8)
@android.annotation.SuppressLint("LocalContextResourcesRead")
@Composable
fun sbPluralStringResource(id: Int, count: Int, vararg args: Any): String {
    val res = LocalSbAppResources.current ?: LocalContext.current.resources
    return if (args.isEmpty()) res.getQuantityString(id, count) else res.getQuantityString(id, count, *args)
}
/** Resolved locale for every formatter; outside a theme use the configuration as before. */
@Composable
@ReadOnlyComposable
fun sbAppLocale(): Locale = LocalSbAppLocale.current ?: LocalConfiguration.current.locales[0]

/** The app's own table (another language, or words from strings.xml); null = the built-in table of the locale. */
val LocalSbMessages = staticCompositionLocalOf<SbMessages?> { null }

/** The words table of this screen: LocalSbMessages, else the built-in table of the screen's language. */
@Composable
@ReadOnlyComposable
fun sbMessages(): SbMessages =
    LocalSbMessages.current ?: sbMessagesFor(sbAppLocale())

/** A count in the screen's language: „10.000“ (de), „10,000“ (en); never U+202F or U+2009 (D22). */
@Composable
@ReadOnlyComposable
fun sbFormatCount(value: Int): String =
    NumberFormat.getIntegerInstance(sbAppLocale()).format(value)
        .replace(' ', ' ')
        .replace(' ', ' ')
